// On extrait les données
const device = msg.payload.end_device_ids.device_id;
const time = msg.payload.received_at;
const sensors = msg.payload.uplink_message.decoded_payload;

// On reconstruit un nouveau message propre
msg.payload = {
    device: device,
    timestamp: time,
    temperature: sensors.temperature,
    humidity: sensors.humidity,
    luminosity: sensors.luminosity
};

return msg;

// Exemple : On veut envoyer "1" pour allumer un ventilo, "0" pour éteindre
// TTN demande du Base64. "1" en Base64 est "MQ=="
const command = (msg.payload.temperature > 5) ? "AQ==" : "AA==";

msg.payload = {
    "downlinks": [{
        "f_port": 15,            // Port utilisé par ton code ESP32
        "frm_payload": command,  // La commande en Base64
        "priority": "NORMAL"
    }]
};

// Très important : Le topic MQTT pour le Downlink TTN est spécifique
// Remplace par tes vrais IDs
const appID = "ynov-test-m1";
const devID = "ra3172-capteur-3";
msg.topic = `v3/${appID}@ttn/devices/${devID}/down/push`;

return msg;
